13	
14	/**
15	 * Assigns a shared {@code householdId} to owners that intentionally share a household.
16	 *
17	 * <p>Runs after {@link BuildOwner} (which produces the new {@link Owner}) and only acts when the
18	 * request opted in with {@code sharesHousehold=true}. It finds every existing owner with the same
19	 * last name and address (last name case-insensitive with collapsed whitespace, address in its
20	 * normalized form per {@link OwnerAddress}, exactly as {@link CheckUniqueHousehold} decides a
21	 * collision). When at least one such owner exists — the
22	 * household this owner is joining — a stable identifier is chosen and stamped onto the new owner
23	 * and back-filled onto the existing members, so every owner in the household reports the same
24	 * {@code householdId}.
25	 *
26	 * <p>The identifier is derived deterministically from the normalized last name and address, so it
27	 * is the same value each joining owner computes regardless of ordering; an identifier already
28	 * present on an existing member is reused as-is.
29	 */
30	public class AssignHousehold {
31	
32	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
33	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
34	            return;
35	        }
36	        String lastName = normalizeName(owner.getLastName());
37	        String address = OwnerAddress.normalizeForCompare(owner.getAddress());
38	        List<Owner> household = new ArrayList<>();
39	        for (Owner existing : ownerRepository.findAll()) {
40	            if (lastName.equals(normalizeName(existing.getLastName()))
41	                    && address.equals(OwnerAddress.normalizeForCompare(existing.getAddress()))) {
42	                household.add(existing);
43	            }
44	        }
45	        if (household.isEmpty()) {
46	            // sharesHousehold was set but no existing member shares this address; nothing to join.
47	            return;
48	        }
49	        String householdId = existingHouseholdId(household);
50	        if (householdId == null) {
51	            householdId = deriveHouseholdId(lastName, address);
52	        }
53	        owner.setHouseholdId(householdId);
54	        for (Owner member : household) {
55	            if (!householdId.equals(member.getHouseholdId())) {
56	                member.setHouseholdId(householdId);
57	                ownerRepository.save(member);
58	            }
59	        }
60	    }
61	
62	    private static String existingHouseholdId(List<Owner> household) {
